const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels = {preparing:'Подготовка',active:'Заседание идёт',paused:'Перерыв',closed:'Завершено',pending:'Ожидает',opened:'Голосование',present:'Очно',remote:'Дистанционно',mixed:'Смешанный',regular:'Очередное',extraordinary:'Внеочередное',emergency:'Экстренное',absent:'Отсутствует',left:'Покинул',member:'Член совета',chairman:'Председатель',secretary:'Секретарь',observer:'Наблюдатель',coordinator:'Координатор',for:'За',against:'Против',abstain:'Воздержался',open:'Открытое',roll_call:'Поимённое',secret:'Тайное',speak:'Выступление',question:'Вопрос',dissent:'Особое мнение',conflict:'Конфликт интересов',roll_call_request:'Поимённое голосование',granted:'Слово предоставлено',rejected:'Отклонено',deferred:'Отложено',done:'Завершено',todo:'К выполнению',doing:'В работе',warning:'Предупреждение',reprimand:'Выговор',appealed:'Обжалуется',final:'Вступил в силу',draft:'На рассмотрении',proposed:'Предложено',cancelled:'Отменено',curators:'Кураторский состав',federal:'Федеральное руководство',council:'Совет',roll_call:'Поимённое',agenda_amendment:'Поправка к повестке'};
const procedures = {decision:'Организационное решение',agenda:'Утверждение / изменение повестки',resolution:'Резолюция',chair_election:'Выборы председателя',secretary_election:'Выборы секретаря',group_create:'Создание внутреннего комитета',group_close:'Ликвидация внутреннего комитета',charter_amendment:'Изменение устава',chair_recall:'Отзыв председателя',reprimand:'Выговор решением совета',veto_override:'Преодоление вето',mandate_termination:'Прекращение мандата',single_reading:'Рассмотрение в одном чтении',agenda_amendment:'Изменение повестки в ходе заседания',circumstances:'Существенное изменение обстоятельств',appeal:'Рассмотрение апелляции',break:'Объявление перерыва',amendment:'Поправка к проекту',speech_rules:'Изменение регламента выступлений'};
let state = null, page = localStorage.getItem('council-page') || 'dashboard', meetingId = localStorage.getItem('council-meeting') || null, meetingTab = 'session', modalSubmit = null, busy = false, lastSignature = '', reference = null;
const office = () => state?.me?.roles?.some(r=>['chairman','secretary'].includes(r));
const chair = () => state?.me?.roles?.includes('chairman');
const current = () => state?.meetings?.find(m=>String(m.id)===String(meetingId));
const memberName = id => state?.members?.find(m=>String(m.id)===String(id))?.name || 'Участник';
const date = v => v ? new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'}).format(new Date(v)) : 'Дата не указана';
const shortDate = v => v ? new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'Europe/Moscow'}).format(new Date(v)) : 'Без срока';
const translate = v => labels[v] || v || '—';
const badge = (text,kind='') => `<span class="badge ${kind}">${esc(text)}</span>`;
const bt = (text,command,data={},kind='',disabled=false) => `<button type="button" class="button ${kind}" data-command="${esc(command)}" data-payload="${esc(JSON.stringify(data))}" ${disabled?'disabled':''}>${esc(text)}</button>`;
const act = (text,action,data={},kind='',disabled=false) => bt(text,'action',{action,...data},kind,disabled);
const empty = (title,description='',button='') => `<div class="empty"><div class="empty-symbol" aria-hidden="true">⊞</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${button}</div>`;
const heading = (title,subtitle,actions='') => `<div class="heading"><div><div class="eyebrow">Малый совет / Рабочее пространство</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;
const memberOptions = () => (state?.members||[]).filter(m=>m.active!==false).map(m=>[m.id,m.name]);
const meetingOptions = () => (current()?.questions||[]).map(q=>[q.id,`${q.order_num}. ${q.title}`]);
const adoptionOptions = () => (state?.meetings||[]).flatMap(m=>(m.questions||[]).filter(q=>q.result?.passed&&q.announced_at&&(!q.veto||q.veto.overridden_at)).map(q=>[q.id,q.title]));
const formField = (name,label,type='text',extra={}) => ({name,label,type,...extra});
const f = formField;
const titleField = () => f('title','Название','text',{required:true,maxLength:300});
const textField = (name='text',label='Описание') => f(name,label,'textarea',{maxLength:20000});
const memberField = (name='member_id',label='Член совета',required=true) => f(name,label,'select',{options:memberOptions(),required});
const questionField = (name='question_id',label='Вопрос повестки',required=false) => f(name,label,'select',{options:meetingOptions(),required});
const num = value => value===''?null:String(value);
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6000);}
async function api(path,body){const res=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const data=await res.json().catch(()=>({error:'Сервер вернул некорректный ответ'}));if(!res.ok)throw new Error(data.error||data.detail||'Не удалось выполнить действие');return data;}
function setState(next){state=next.state||next;state.meetings||=[];state.members||=[];for(const k of ['groups','tasks','correspondence','initiatives','discipline'])state[k]||=[];if(!current())meetingId=state.meetings.find(m=>m.status==='active')?.id||state.meetings[0]?.id||null;if(meetingId)localStorage.setItem('council-meeting',meetingId);lastSignature=JSON.stringify(state);}
async function action(payload,success='Сохранено'){if(busy)return;busy=true;try{const data=await api('/api/action',{meeting_id:meetingId,...payload});if(data.display_url){openDialog('Ссылка на табло',[f('url','Ссылка для отдельного экрана','text',{value:new URL(data.display_url,location.origin).href,readonly:true})],async()=>{},'Готово');$('#dialog-fields').insertAdjacentHTML('beforeend',`<a class="button wide" href="${esc(data.display_url)}" target="_blank" rel="noopener">Открыть табло в новой вкладке ↗</a><p style="margin-top:15px">Доступ только для просмотра. Ссылка действует 12 часов.</p>`);}setState(data);if(payload.action==='meeting.create'){meetingId=state.meetings.at(-1)?.id;page='meetings';}render();if(success)toast(success);return data;}catch(err){toast(err.message,true);err.reported=true;throw err;}finally{busy=false;}}
function fieldHTML(field){const {name,label,type,required,value='',options=[],help}=field;const props=`name="${esc(name)}" id="field-${esc(name)}" ${required?'required':''} ${field.readonly?'readonly':''} ${field.maxLength?`maxlength="${field.maxLength}"`:''}`;let input;if(type==='select')input=`<select ${props}>${!required?'<option value="">Не указано</option>':''}${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;else if(type==='textarea')input=`<textarea ${props} rows="4" placeholder="${esc(field.placeholder||'')}">${esc(value)}</textarea>`;else if(type==='checkbox')return `<label class="checkbox-field"><input type="checkbox" ${props} ${value?'checked':''}>${esc(label)}</label>${help?`<div class="field-help">${esc(help)}</div>`:''}`;else if(type==='checks')return `<label>${esc(label)}</label><div class="check-options">${options.map(([v,l])=>`<label class="check-option"><input type="checkbox" name="${esc(name)}" value="${esc(v)}" ${(field.values||[]).includes(v)?'checked':''}>${esc(l)}</label>`).join('')}</div>${help?`<div class="field-help">${esc(help)}</div>`:''}`;else input=`<input type="${esc(type)}" ${props} value="${esc(value)}" ${field.min!==undefined?`min="${field.min}"`:''} ${field.max!==undefined?`max="${field.max}"`:''} ${field.minLength?`minlength="${field.minLength}"`:''} placeholder="${esc(field.placeholder||'')}">`;return `<div class="field"><label for="field-${esc(name)}">${esc(label)}${required?' *':''}</label>${input}${help?`<div class="field-help">${esc(help)}</div>`:''}</div>`;}
function openDialog(title,fields,onSubmit,submit='Сохранить',description=''){const modal=$('#modal');$('#dialog-title').textContent=title;$('#dialog-fields').innerHTML=(description?`<p>${esc(description)}</p>`:'')+fields.map(fieldHTML).join('');$('#dialog-error').textContent='';$('#dialog-submit').textContent=submit;modalSubmit=async()=>{const fd=new FormData($('#dialog-form')),data={};for(const field of fields){if(field.type==='checks')data[field.name]=fd.getAll(field.name);else if(field.type==='checkbox')data[field.name]=fd.has(field.name);else data[field.name]=fd.get(field.name)??'';}return onSubmit(data);};if(!modal.open)modal.showModal();}
function actionForm(title,actionName,fields,data={},submit='Сохранить',description='',transform=x=>x){openDialog(title,fields,async(values)=>{await action({action:actionName,...data,...transform(values)});},submit,description);}
function roleNames(roles){return (roles||[]).map(translate).join(' · ');}
function renderAuth(){const setup=state.setupRequired;$('#account').innerHTML='';$('#shell').innerHTML=`<main class="auth-layout"><section class="auth-intro"><div class="eyebrow">Рабочее пространство совета</div><h1>Вместе —<br>к новым<br><em>решениям.</em></h1><p>От проекта повестки до готового протокола.<br>Заседания, голосования и контроль исполнения по уставу Малого совета.</p><div class="auth-divider" aria-hidden="true"><i></i><i></i><i></i></div></section><section class="card auth-card"><a href="/public" class="public-auth-link">Подать обращение или инициативу без входа ↗</a><div class="eyebrow">${setup?'Первый запуск':'Личный кабинет'}</div><h2>${setup?'Настроим совет':'Добро пожаловать'}</h2><p>${setup?'Создайте первую учётную запись. После настройки добавьте членов совета и проведите выборы должностных лиц.':'Войдите под своей учётной записью для участия в работе совета.'}</p><form id="auth-form">${setup?fieldHTML(f('name','Ваше имя','text',{required:true,maxLength:150})):fieldHTML(f('member_id','Член совета','select',{required:true,options:(state.members||[]).map(m=>[m.id,m.name])}))}${fieldHTML(f('password','Пароль','password',{required:true,minLength:setup?10:1,help:setup?'Не менее 10 символов. У каждого участника будет свой пароль.':''}))}<div id="auth-error" class="form-error" role="alert"></div><button type="submit" class="button wide">${setup?'Создать пространство':'Войти в пространство'} <span aria-hidden="true">↗</span></button></form></section></main>`;$('#auth-form').addEventListener('submit',async ev=>{ev.preventDefault();const button=ev.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(ev.target));setState(await api(setup?'/api/setup':'/api/login',data));render();}catch(err){$('#auth-error').textContent=err.message;}finally{button.disabled=false;}});}
const navItems=[['dashboard','◫','Обзор'],['public-inbox','✉','Публичные заявки'],['meetings','▤','Заседания'],['members','♙','Состав совета'],['groups','◇','Внутренние комитеты'],['tasks','☷','Поручения'],['inbox','↗','Обращения'],['initiatives','＋','Инициативы'],['discipline','§','Разбирательства'],['analytics','▥','Участие'],['rules','≡','Устав и правила']];
function render(){if(!state?.me){renderAuth();return;}$('#account').innerHTML=`<div class="account-info"><strong>${esc(state.me.name)}</strong><small>${esc(roleNames(state.me.roles))}</small></div>${bt('Пароль','password-form',{},'outline small')}${bt('Выйти','logout',{},'outline small')}`;$('#shell').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="sidebar-label">ПРОСТРАНСТВО</div><nav class="navigation" aria-label="Разделы совета">${navItems.map(([id,icon,label])=>`<button class="nav-button ${page===id?'active':''}" data-command="navigate" data-payload="${esc(JSON.stringify({page:id}))}" ${page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}${id==='tasks'&&state.tasks.filter(t=>t.status!=='done').length?`<span class="nav-count">${state.tasks.filter(t=>t.status!=='done').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><strong>Общее дело.</strong>Обсуждаем. Решаем.<br>Действуем.<br><a href="/public" target="_blank" rel="noopener">Открытая приёмная ↗</a><br>${office()?'<a href="/api/export" download>Резервная копия данных ↗</a>':''}</div></aside><main id="content">${state.me.active===false?'<div class="notice danger">Мандат прекращён. Голосование недоступно; материалы и подача апелляции доступны в разделе «Разбирательства».</div>':''}${renderPage()}</main></div>`;}
function renderPage(){switch(page){case'public-inbox':return publicInbox();case'dashboard':return dashboard();case'meetings':return meetings();case'members':return members();case'groups':return groups();case'tasks':return tasks();case'inbox':return inbox();case'initiatives':return initiatives();case'discipline':return discipline();case'analytics':return analytics();case'rules':return rules();default:page='dashboard';return dashboard();}}
function dashboard(){const live=state.meetings.find(m=>['active','paused'].includes(m.status)),next=state.meetings.filter(m=>m.status==='preparing').sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at))[0],upcoming=live||next;const todo=state.tasks.filter(t=>t.status!=='done'),overdue=todo.filter(t=>t.due_date&&new Date(t.due_date)<new Date());return heading('Работа совета','Всё готово для следующего решения.',office()?bt('＋ Новое заседание','meeting-form'):'')+`<div class="stats"><div class="stat"><div class="stat-value">${state.meetings.length}</div><div class="stat-label">Заседаний в пространстве</div></div><div class="stat"><div class="stat-value">${state.members.filter(m=>m.active!==false).length} <span style="font-size:13px;color:#a3b5a6">/ 16</span></div><div class="stat-label">Членов установленного состава</div></div><div class="stat"><div class="stat-value">${todo.length}</div><div class="stat-label">Поручений в работе</div></div><div class="stat"><div class="stat-value">${state.groups.filter(g=>!g.closed_at).length}</div><div class="stat-label">Внутренних комитетов</div></div></div><div class="grid"><section class="card dark"><div class="section-kicker" style="color:#9bc8b5">${live?'СЕЙЧАС В СОВЕТЕ':'БЛИЖАЙШЕЕ ЗАСЕДАНИЕ'}${upcoming?badge(translate(upcoming.status)):''}</div>${upcoming?`<h2>${esc(upcoming.title)}</h2><p>${esc(date(upcoming.scheduled_at||upcoming.started_at))} · ${esc(translate(upcoming.format))}</p><div class="actions">${bt(live?'Перейти к заседанию ↗':'Открыть подготовку ↗','open-meeting',{id:upcoming.id})}</div>`:`<h2>Следующее заседание<br>начинается здесь.</h2><p>Соберите повестку, подготовьте материалы и пригласите участников.</p>${office()?bt('Подготовить заседание','meeting-form'):''}`}</section><section class="card"><div class="card-head"><h3>Требует внимания</h3>${badge(overdue.length?'Есть просроченные сроки':'Рабочий ритм',overdue.length?'warn':'good')}</div>${overdue.length?overdue.slice(0,3).map(t=>`<div class="row"><div><div class="row-title">${esc(t.title)}</div><div class="row-meta overdue">Срок: ${esc(shortDate(t.due_date))} · ${esc(memberName(t.assignee_id))}</div></div>${bt('Открыть','navigate',{page:'tasks'},'text')}</div>`).join(''):`<p>Поручения с истёкшим сроком не найдены.</p>`}${(state.alerts||[]).slice(0,5).map(a=>`<div class="notice" style="margin-top:10px">${esc(a.text)}</div>`).join('')}<div class="notice info" style="margin:15px 0 0">Кворум — 9 из 16 членов. Очередные заседания проводятся не реже одного раза в две недели.</div></section></div><section class="card" style="margin-top:20px"><div class="card-head"><h3>Последние заседания</h3>${bt('Все заседания →','navigate',{page:'meetings'},'text')}</div>${state.meetings.length?state.meetings.slice().reverse().slice(0,4).map(meetingRow).join(''):empty('Пока нет заседаний','Создайте первое заседание — программа проведёт вас через основные этапы.')}</section>`;}
function meetingRow(m){return `<div class="row"><div class="row-main"><div class="row-title">${esc(m.title)}</div><div class="row-meta">${esc(date(m.scheduled_at||m.started_at))} · ${esc(translate(m.format))} · ${(m.questions||[]).length} вопросов</div></div><div class="actions">${badge(translate(m.status),m.status==='active'?'live':'')}${bt('Открыть ↗','open-meeting',{id:m.id},'secondary small')}</div></div>`;}
function meetings(){if(!current())return heading('Заседания','Полный цикл работы: подготовка, обсуждение, голосование, протокол.',office()?bt('＋ Новое заседание','meeting-form'):'')+empty('Начните с первого заседания','Повестка и протокол формируются в процессе работы.',office()?bt('Создать заседание','meeting-form'):'');const m=current(),q=quorumOf(m);return heading('Заседания','Прозрачные процедуры. Каждое решение на своём месте.',`${bt('Список','meeting-list',{},'secondary')}${office()?bt('＋ Новое','meeting-form'):''}`)+`<div class="meeting-picker" style="margin-bottom:18px"><select id="meeting-picker" aria-label="Выбрать заседание">${state.meetings.slice().reverse().map(x=>`<option value="${x.id}" ${String(x.id)===String(m.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><section class="card meeting-banner"><div class="meeting-banner-top"><div><div class="row-title">${esc(m.title)}</div><div class="row-meta" style="color:#9cbdac">${esc(translate(m.meeting_type))} · ${esc(translate(m.format))}${m.location?' · '+esc(m.location):''}</div></div>${badge(translate(m.status),m.status==='active'?'live':'')}</div><div class="meeting-banner-body"><div><div class="quorum-number">${q.present} <span style="color:#a5b7a9;font-size:17px">/ 16</span> ${badge(q.has_quorum?'Кворум есть':'Нужно 9 членов',q.has_quorum?'good':'warn')}</div><div class="quorum-label">Очно + идентифицированные дистанционные участники</div><div class="progress"><span style="width:${Math.min(q.present/16*100,100)}%"></span></div></div><div class="meeting-dates">${esc(date(m.scheduled_at||m.started_at))}<br>${m.published_at?'Повестка опубликована '+esc(shortDate(m.published_at)):'Повестка ещё не опубликована'}</div></div></section>${meetingWarnings(m)}<div class="subtabs" role="tablist">${[['session','Повестка и голосование'],['attendance','Участники'],['discussion','Быстрый протокол'],['documents','Протокол и материалы']].map(([id,l])=>`<button role="tab" aria-selected="${meetingTab===id}" class="subtab ${meetingTab===id?'active':''}" data-command="meeting-tab" data-payload="${esc(JSON.stringify({tab:id}))}">${l}</button>`).join('')}</div>${meetingTab==='attendance'?attendance(m):meetingTab==='discussion'?discussion(m):meetingTab==='documents'?documents(m):session(m)}`;}
function quorumOf(m){if(m.quorum)return m.quorum;let present=0;for(const member of state.members){const a=m.attendance?.[member.id];if(member.active!==false&&a?.role!=='observer'&&(a?.status==='present'||a?.status==='remote'&&a.identified))present++;}return {present,total:16,needed:9,has_quorum:present>=9};}
function meetingWarnings(m){let s='';if(!quorumOf(m).has_quorum&&m.status!=='closed')s+='<div class="notice">Без кворума можно обсуждать вопросы и вести записи. Голосование станет доступно после регистрации не менее 9 членов совета.</div>';if(m.status==='active'&&!m.agenda_approved)s+='<div class="notice info">Сначала утвердите повестку: создайте вопрос с процедурой «Утверждение / изменение повестки», проведите голосование и объявите результат.</div>';if(m.reason)s+=`<div class="notice info">Основание созыва: ${esc(m.reason)}</div>`;return s;}
function session(m){const qs=m.questions||[],active=qs.find(q=>q.status==='opened')||qs.find(q=>q.id===m.current_question_id),latest=active||qs.filter(q=>q.status==='closed').at(-1);return `${office()?`<div class="actions" style="margin-bottom:20px">${m.status==='preparing'?`${act('Подготовить повестку','meeting.publish',{},'secondary',!!m.published_at)}${m.published_at?`<a class="button secondary" href="/api/agenda/${encodeURIComponent(m.id)}" download>Скачать для рассылки ↧</a>${bt('Подтвердить рассылку','confirm',{action:'meeting.sent',title:'Подтвердить рассылку повестки?',description:'Подтверждайте после фактической отправки повестки всем членам совета. Программа сохранит время рассылки.'},'secondary',!!m.agenda_sent_at)}`:''}${act('Открыть заседание','meeting.start',{},'',!m.agenda_sent_at)}${bt('Перенести время','reschedule-form',{},'outline')}`:''}${m.status==='active'?`${act('Перерыв','meeting.pause',{},'secondary')}${bt('Закрыть заседание','confirm',{action:'meeting.close',title:'Закрыть заседание?',description:'Сначала завершите голосования и объявите результаты. Заседание перейдёт в архив.'},'outline')}`:''}${m.status==='paused'?act('Продолжить заседание','meeting.resume'):''}${m.status!=='closed'?bt('＋ Вопрос повестки','question-form',{},'secondary'):''}${bt('Вести протокол','meeting-tab',{tab:'discussion'},'secondary')}${act('Открыть табло','display.create',{},'outline')}</div>`:''}<div class="session-layout"><section class="card"><div class="card-head"><h3>Повестка дня</h3>${badge(qs.length+' вопросов')}</div>${qs.length?qs.map(q=>questionRow(q,m)).join(''):empty('Повестка пока пуста','Начните с утверждения повестки, затем добавьте основные вопросы и материалы.',office()?bt('Добавить вопрос','question-form'):'')}</section><div>${latest?votePanel(latest,m):`<section class="card mint"><div class="section-kicker">ПРОСТРАНСТВО РЕШЕНИЙ</div><h2>${m.status==='preparing'?'Готовимся к заседанию':'Обсуждение открыто'}</h2><p>Здесь появится бюллетень, когда председательствующий откроет голосование.</p><div class="rule-line">Без ограничения в 10 секунд. Голосование завершает председательствующий.</div></section>`}<section class="card"><h3>Участвуйте в обсуждении</h3><p>Запросите слово, задайте вопрос или зафиксируйте позицию в протоколе.</p><div class="actions">${bt('Выступить','request-form',{type:'speak'},'secondary')}${bt('Задать вопрос','request-form',{type:'question'},'secondary')}${bt('Особое мнение','request-form',{type:'dissent'},'outline')}${bt('Конфликт интересов','request-form',{type:'conflict'},'outline')}</div></section></div></div>`;}
function questionRow(q,m){const result=q.result,open=q.status==='opened';return `<div class="question-row ${open?'current':''}"><div class="question-index">${String(q.order_num||1).padStart(2,'0')}</div><div class="row-main"><div class="row-title">${esc(q.title)}</div><div class="row-meta">${badge(procedures[q.procedure]||q.procedure)}${badge(translate(q.status),open?'live':result?.passed?'good':'')}${q.reading?badge(q.reading+' чтение'):''}${q.announced_at?badge('Результат объявлен','good'):''}${q.veto&&!q.veto.overridden_at?badge('Вето','danger'):''}</div>${q.status==='pending'&&q.vote_type!=='roll_call'?`<div style="margin-top:9px">${act('Потребовать поимённое голосование','request.add',{type:'roll_call',question_id:q.id,text:'Требование поимённого голосования'},'small text')}</div>`:''}${q.text?`<details style="margin-top:9px"><summary class="row-meta">Текст проекта</summary><p class="long-text">${esc(q.text)}</p></details>`:''}${office()&&m.status==='active'?`<div class="actions question-controls">${q.status==='pending'?act('Открыть голосование','question.open',{question_id:q.id},'small secondary',!quorumOf(m).has_quorum):''}${open?act('Завершить','question.close',{question_id:q.id},'small'):''}${q.status==='closed'&&!q.announced_at&&!(q.result?.tiedIds?.length)?act('Объявить результат','question.announce',{question_id:q.id},'small secondary'):''}${q.result?.tiedIds?.length>1?act('Повторный тур','question.runoff',{question_id:q.id},'small'):''}${chair()&&q.status==='closed'&&q.result?.passed&&!q.announced_at&&!q.veto?bt('Вето','veto-form',{question_id:q.id},'small danger'):''}${q.veto&&!q.veto.overridden_at?act('Поставить преодоление вето','question.override',{question_id:q.id},'small secondary'):''}${q.status==='closed'&&q.result?bt('Результат','result',{question_id:q.id},'small text'):''}</div>`:''}</div></div>`;}
function votePanel(q,m){const open=q.status==='opened',r=q.result||{},myVote=q.my_vote||q.votes?.find(v=>String(v.member_id)===String(state.me.id)),att=m.attendance?.[state.me.id],eligible=att?.role!=='observer'&&(att?.status==='present'||att?.status==='remote'&&att.identified);return `<section class="card vote-panel"><div class="section-kicker"><span>${open?'<span class="status-dot"></span>ГОЛОСОВАНИЕ ОТКРЫТО':'ИТОГИ ГОЛОСОВАНИЯ'}</span>${badge(q.vote_type==='secret'?'Тайное':q.vote_type==='roll_call'?'Поимённое':'Открытое')}</div><h2>${esc(q.title)}</h2>${q.decision_text?`<p class="long-text">${esc(q.decision_text)}</p>`:''}<div class="rule-line">${['charter_amendment','chair_recall','reprimand','veto_override'].includes(q.procedure)?'Не менее 11 голосов «за».':q.procedure==='chair_election'?'Наибольшее число голосов; при равенстве — повторный тур.':'Больше половины участвующих в голосовании.'} Кворум — 9 из 16.</div>${open?`${myVote?`<div class="notice info">Ваш голос зафиксирован${myVote.value?': '+esc(translate(myVote.value)):''}.</div>`:!eligible?'<div class="notice">Для голосования необходима регистрация присутствия секретарём.</div>':''}${q.procedure==='chair_election'?`<div>${(q.choices||[]).map(c=>act(c.text,'vote.cast',{question_id:q.id,choice_id:c.id},'vote-choice',!eligible||!!myVote)).join('')}${act('Воздержаться','vote.cast',{question_id:q.id,value:'abstain'},'vote-choice secondary',!eligible||!!myVote)}</div>`:`<div class="vote-buttons">${act('✓ ЗА','vote.cast',{question_id:q.id,value:'for'},'',!eligible||!!myVote)}${act('× ПРОТИВ','vote.cast',{question_id:q.id,value:'against'},'danger',!eligible||!!myVote)}${act('ВОЗДЕРЖАЛСЯ','vote.cast',{question_id:q.id,value:'abstain'},'secondary',!eligible||!!myVote)}</div>`}<div class="row-meta">Один участник — один голос. Учёт ведётся автоматически.</div>`:`${q.procedure==='chair_election'?`<div>${(r.choices||[]).map(c=>`<div class="row"><span class="row-title">${esc(c.text)}</span><strong>${c.votes||0}</strong></div>`).join('')}</div>`:`<div class="vote-result"><div><strong>${r.for||0}</strong><small>за</small></div><div><strong>${r.against||0}</strong><small>против</small></div><div><strong>${r.abstain||0}</strong><small>воздержались</small></div></div>`}<h3>${r.tiedIds?.length>1?'Повторное голосование':r.passed?'Решение принято':'Решение не принято'}</h3><p>${esc(r.reason||'Результат зафиксирован')}${r.needed?' · Требовалось: '+r.needed:''}</p>${q.veto?`<div class="notice ${q.veto.overridden_at?'info':'danger'}">${q.veto.overridden_at?'Вето преодолено':'Заявлено вето'}: ${esc(q.veto.reason)}</div>`:''}`}</section>`;}
function attendance(m){return `<section class="card"><div class="card-head"><div><h3>Регистрация участников</h3><p style="margin:5px 0 0">Время прибытия и ухода сохраняется автоматически. Наблюдатели не учитываются в кворуме.</p></div>${office()&&m.status!=='closed'?bt('＋ Наблюдатель','observer-form',{},'secondary small'):''}</div>${state.members.map(member=>{const a=m.attendance?.[member.id]||{status:'absent'};return `<div class="attendance-row"><div><div class="row-title">${esc(member.name)}</div><div class="row-meta">${esc(roleNames(member.roles))}${a.arrival_time?' · Прибыл '+esc(new Date(a.arrival_time).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'})):''}</div></div><div>${office()&&m.status!=='closed'?`<select data-attendance="${member.id}" aria-label="Участие ${esc(member.name)}">${['absent','present','remote','left'].map(v=>`<option value="${v}" ${a.status===v?'selected':''}>${translate(v)}</option>`).join('')}</select>`:badge(translate(a.status),['present','remote'].includes(a.status)?'good':'')}</div><div class="attendance-extra">${a.status==='remote'?`${badge(a.identified?'Личность подтверждена':'Нужна идентификация',a.identified?'good':'warn')}${office()&&!a.identified&&m.status!=='closed'?act('Подтвердить','attendance.set',{member_id:member.id,status:'remote',identified:true},'small secondary'):''}`:''}${a.excused?badge('Уважительная причина','good'):''}${office()&&m.status!=='closed'?bt(a.excused?'Изменить причину':'Уважительная причина','excuse-form',{member_id:member.id},'small text'):''}</div></div>`}).join('')}${(m.observers||[]).length?`<h3 style="margin-top:26px">Приглашённые без права голоса</h3>${m.observers.map(o=>`<div class="row"><div><div class="row-title">${esc(o.name)}</div><div class="row-meta">${esc(translate(o.role||'observer'))} · ${esc(translate(o.status||'present'))}</div></div>${badge('Без права голоса')}</div>`).join('')}`:''}</section>`;}
function discussion(m){const reqs=m.requests||[],notes=m.notes||[];return `${quickProtocol(m)}<div class="grid"><section class="card"><div class="card-head"><h3>Очередь выступлений</h3>${bt('＋ Запрос','request-form',{type:'speak'},'secondary small')}</div>${reqs.length?reqs.map(r=>`<div class="row"><div class="row-main"><div class="row-title">${esc(r.member_name||memberName(r.member_id))} · ${esc(translate(r.type))}</div>${r.text?`<p class="long-text" style="margin:8px 0">${esc(r.text)}</p>`:''}<div class="row-meta">${badge(translate(r.status),r.status==='granted'?'live':'')} ${r.speech_seconds?Math.round(r.speech_seconds/60)+' мин.':''}${r.status==='granted'&&r.started_at?` <strong data-speaker-start="${esc(r.started_at)}" data-seconds="${r.speech_seconds||180}"></strong>`:''}${r.started_at?` · Слово с ${esc(date(r.started_at))}`:''}</div></div>${office()&&m.status!=='closed'?`<div class="actions">${['pending','deferred'].includes(r.status)?`${act('Дать слово','request.handle',{request_id:r.id,status:'granted'},'small')}${act('Отложить','request.handle',{request_id:r.id,status:'deferred'},'secondary small')}${act('Отклонить','request.handle',{request_id:r.id,status:'rejected'},'danger small')}`:''}${r.status==='granted'?act('Завершить','request.handle',{request_id:r.id,status:'done'},'secondary small'):''}</div>`:''}</div>`).join(''):'<div class="list-empty">Запросов пока нет. Участники могут записаться на выступление.</div>'}</section><section class="card"><div class="card-head"><h3>Ход обсуждения</h3>${office()&&m.status!=='closed'?bt('＋ Запись','note-form',{},'secondary small'):''}</div>${noteTimeline(m)}</section></div>`;}
function documents(m){const closed=(m.questions||[]).filter(q=>q.status==='closed');return `<div class="grid"><section class="card"><div class="eyebrow">Делопроизводство</div><h2>Протокол формируется<br>во время заседания.</h2><p>Дата и формат, участники и кворум, ход обсуждения, решения, голосования, особые мнения и вето собираются в единый документ.</p><div class="actions"><a class="button" href="/api/protocol/${encodeURIComponent(m.id)}" target="_blank" rel="noopener">Открыть / печать ↗</a><a class="button secondary" href="/api/protocol/${encodeURIComponent(m.id)}?public=1" target="_blank" rel="noopener">Публичная версия ↗</a></div><div class="notice info" style="margin-top:20px;margin-bottom:0">Публичный текст доступен для подготовки сообщения участникам движения. Перед публикацией проверьте состав раскрываемых сведений.</div></section><section class="card"><h3>Контроль готовности</h3>${m.status==='closed'?`<div class="notice info">Решения Координатору: ${m.coordinator_sent_at?'переданы '+esc(shortDate(m.coordinator_sent_at)):'передать в течение 24 часов'}${office()&&!m.coordinator_sent_at?'<div style="margin-top:10px">'+bt('Подтвердить передачу','coordinator-form',{},'secondary small')+'</div>':''}</div>`:''}<div class="row"><span class="row-title">Повестка</span>${badge(m.published_at?'Опубликована':'Не опубликована',m.published_at?'good':'warn')}</div><div class="row"><span class="row-title">Утверждение повестки</span>${badge(m.agenda_approved?'Утверждена':'Ожидает',m.agenda_approved?'good':'warn')}</div><div class="row"><span class="row-title">Рассмотренные вопросы</span>${badge(closed.length+' / '+(m.questions||[]).length)}</div><div class="row"><span class="row-title">Объявлены результаты</span>${badge(closed.filter(q=>q.announced_at).length+' / '+closed.length)}</div><div class="row"><span class="row-title">Состояние</span>${badge(m.status==='closed'?'Закрыто':'Протокол дополняется',m.status==='closed'?'good':'')}</div></section></div><section class="card" style="margin-top:18px"><div class="card-head"><h3>Материалы и обоснования</h3>${office()&&m.status!=='closed'?bt('＋ Прикрепить файл','material-form',{},'secondary small'):''}</div>${(state.materials||[]).filter(f=>f.meeting_id===m.id).map(f=>`<div class="row"><a href="/api/material/${encodeURIComponent(f.id)}" download>${esc(f.filename)}</a><span class="row-meta">${Math.ceil(f.size/1024)} КБ</span></div>`).join('')}${(m.questions||[]).length?(m.questions||[]).map(q=>`<details class="row" style="display:block"><summary class="row-title">${esc(q.order_num+'. '+q.title)}</summary><div style="margin-top:15px"><p class="long-text">${esc(q.text||'Текст проекта не приложен.')}</p>${q.decision_text?`<h4>Формулировка решения</h4><p class="long-text">${esc(q.decision_text)}</p>`:''}</div></details>`).join(''):'<p>Тексты проектов будут доступны после заполнения повестки.</p>'}</section>`;}
function members(){return heading('Состав совета','Установленная численность — 16 членов. Координатор и наблюдатели не голосуют.',office()?bt('＋ Добавить члена','member-form'):'')+`<div class="notice info">Председатель и секретарь избираются на заседании. Учётная запись участника не заменяет решение о предоставлении мандата.</div><section class="card">${state.members.length?state.members.map(m=>`<div class="row"><div class="row-main"><div class="row-title">${esc(m.name)}</div><div class="role-list">${(m.roles||[]).map(r=>badge(translate(r),r==='chairman'?'good':'')).join('')}${m.adult===false?badge('Несовершеннолетний'):''}${m.active===false?badge('Мандат неактивен','warn'):''}</div></div><div class="row-meta">${esc(m.telegram||'')}</div></div>`).join(''):empty('Состав пока не заполнен')}</section>`;}
function groups(){return heading('Внутренние комитеты','Проекты, добровольное участие и ежемесячные отчёты.',office()?bt('＋ Оформить создание','group-form'):'')+`<div class="notice info">Внутренний комитет создаётся решением совета. Руководителя назначает председатель. Участие во внутреннем комитете не предоставляет права голоса в совете.</div>${state.groups.length?`<div class="grid">${state.groups.map(g=>`<section class="card"><div class="card-head"><h3>${esc(g.name)}</h3>${badge(g.closed_at?'Закрыта':'Работает',g.closed_at?'':'good')}</div><p class="long-text">${esc(g.description||'')}</p><div class="row-meta">Руководитель: ${esc(g.head_id?memberName(g.head_id):'не назначен')}</div><div class="row-meta">Состав: ${esc((g.members||g.member_ids||[]).map(x=>typeof x==='object'?(x.name||memberName(x.member_id||x.id)):memberName(x)).join(', ')||'Формируется')}</div>${g.reports?.length?`<div class="row-meta">Последний отчёт: ${esc(shortDate(g.reports.at(-1).at))}</div><details><summary class="row-meta">История отчётов</summary>${g.reports.map(r=>`<div class="note">${esc(r.text)}<small>${esc(date(r.at))}</small></div>`).join('')}</details>`:''}${g.report_due_at&&!g.closed_at?`<div class="row-meta">Следующий отчёт: ${esc(shortDate(g.report_due_at))}</div>`:''}${g.external_members?.length?`<div class="row-meta">Участники движения: ${esc(g.external_members.map(x=>x.name).join(', '))}</div>`:''}<div class="actions" style="margin-top:18px">${!g.closed_at?act('Вступить','group.join',{group_id:g.id,member_id:state.me.id},'secondary small'):''}${chair()&&!g.closed_at?bt('Назначить руководителя','group-update-form',{group_id:g.id},'outline small'):''}${!g.closed_at&&(office()||g.head_id===state.me.id)?bt('Сдать отчёт','group-report-form',{group_id:g.id},'outline small'):''}${office()&&!g.closed_at?bt('Участник движения','group-external-form',{group_id:g.id},'outline small'):''}</div></section>`).join('')}</div>`:empty('Внутренние комитеты ещё не оформлены','Сначала примите решение о создании внутреннего комитета, затем оформите его состав.')}`;}
function tasks(){const columns=[['todo','К выполнению'],['doing','В работе'],['done','Готово']];return heading('Поручения','Ответственные, сроки и связь с принятыми решениями.',office()?bt('＋ Поручение','task-form'):'')+`<div class="kanban">${columns.map(([status,label])=>`<section class="kanban-col"><h3>${label} <span class="count">${state.tasks.filter(t=>(t.status||'todo')===status).length}</span></h3>${state.tasks.filter(t=>(t.status||'todo')===status).map(t=>`<article class="task-card"><h4>${esc(t.title)}</h4>${t.description?`<p class="long-text">${esc(t.description)}</p>`:''}<div class="row-meta">${esc(memberName(t.assignee_id))}</div><div class="row-meta ${t.due_date&&new Date(t.due_date)<new Date()&&status!=='done'?'overdue':''}">Срок: ${esc(shortDate(t.due_date))}</div>${(office()||String(t.assignee_id)===String(state.me.id))?`<div class="actions">${status==='todo'?act('Взять в работу','task.update',{task_id:t.id,status:'doing'},'small secondary'):status==='doing'?act('Завершить','task.update',{task_id:t.id,status:'done'},'small'):act('Вернуть в работу','task.update',{task_id:t.id,status:'doing'},'small outline')}</div>`:''}</article>`).join('')||'<div class="row-meta" style="padding:20px 0">Пока нет поручений</div>'}</section>`).join('')}</div>`;}
function inbox(){return heading('Обращения','Ответ члену совета или внутреннему комитету — в течение 7 календарных дней.',bt('＋ Обращение','correspondence-form'))+`<section class="card">${state.correspondence.length?state.correspondence.slice().reverse().map(c=>`<div class="row"><div class="row-main"><div class="row-title">${esc(c.title)}</div><div class="row-meta">Адресат: ${esc(c.recipient_label||(c.group_id?state.groups.find(g=>String(g.id)===String(c.group_id))?.name||'Внутренний комитет':memberName(c.member_id)))} · Срок: ${esc(shortDate(c.due_date||c.deadline))}</div><p class="long-text" style="margin:9px 0 0">${esc(c.text)}</p>${c.reply?`<div class="note">${esc(c.reply)}<small>Ответ зафиксирован</small></div>`:''}</div><div class="actions">${badge(c.reply?'Ответ дан':c.due_date&&new Date(c.due_date)<new Date()?'Просрочено':'Ожидает ответа',c.reply?'good':c.due_date&&new Date(c.due_date)<new Date()?'danger':'warn')}${!c.reply?bt('Ответить','reply-form',{correspondence_id:c.id},'secondary small'):''}</div></div>`).join(''):empty('Обращений пока нет','Программа автоматически рассчитает срок ответа и сохранит переписку.')}</section>`;}
function initiatives(){return heading('Инициативы','Содержательный проект каждого члена совета — не менее одного за созыв.',bt('＋ Инициатива','initiative-form'))+`<section class="card">${state.initiatives.length?state.initiatives.slice().reverse().map(i=>`<div class="row"><div class="row-main"><div class="row-title">${esc(i.title)}</div><div class="row-meta">${esc(i.author_name||memberName(i.member_id||i.created_by))} · ${esc(shortDate(i.created_at))}</div><p class="long-text" style="margin-top:10px">${esc(i.text)}</p></div>${badge('В реестре','good')}</div>`).join(''):empty('Место для следующей инициативы','Опишите проблему и предложите решение. Председатель сможет включить проект в повестку.')}</section>`;}
function discipline(){return heading('Разбирательства','Объяснения, решения и апелляции с сохранением процедуры.',office()?bt('＋ Зарегистрировать','discipline-form'):'')+`<div class="notice info">Показатели участия сами по себе не назначают взыскания. До оформления выговора участнику предоставляются объяснения и апелляция. Оспариваемый выговор не считается окончательным.</div>${mandateCases()}<section class="card">${state.discipline.length?state.discipline.slice().reverse().map(d=>`<div class="row"><div class="row-main"><div class="row-title">${esc(memberName(d.member_id))} · ${esc(translate(d.kind))}</div><div class="row-meta">Инициатор: ${esc(translate(d.issuer))} · ${esc(shortDate(d.created_at))}</div><p class="long-text" style="margin-top:10px">${esc(d.reason)}</p>${d.explanation?`<div class="note">${esc(d.explanation)}<small>Объяснения участника</small></div>`:''}${d.appeal?`<div class="note">${esc(typeof d.appeal==='string'?d.appeal:d.appeal.text||d.appeal.reason||'Апелляция зарегистрирована')}<small>Апелляция</small></div>`:''}${d.resolution?`<p class="long-text">${esc(d.resolution_note||d.resolution)}</p>`:''}</div><div class="actions">${badge(translate(d.status||'draft'),d.status==='final'?'warn':'')}${String(d.member_id)===String(state.me.id)&&d.status!=='cancelled'?bt('Объяснение / апелляция','appeal-form',{discipline_id:d.id},'secondary small'):''}${office()?bt('Оформить итог','discipline-resolve-form',{discipline_id:d.id},'outline small'):''}</div></div>`).join(''):empty('Разбирательств нет','Реестр хранит основания, объяснения, результаты рассмотрения и апелляции.')}</section>`;}
function analytics(){let rows=Array.isArray(state.stats)?state.stats:state.stats?.members||state.stats?.compliance||[];if(!Array.isArray(rows))rows=Object.entries(rows).map(([member_id,data])=>({member_id,...data}));const percent=value=>value==null?'—':`${Math.round(Number(value))}%`;return heading('Участие в работе','Посещаемость, голосования и инициативы за созыв.')+`<div class="stats"><div class="stat"><div class="stat-value">70%</div><div class="stat-label">Участие в заседаниях</div></div><div class="stat"><div class="stat-value">50%</div><div class="stat-label">Участие очно</div></div><div class="stat"><div class="stat-value">75%</div><div class="stat-label">Участие в голосованиях</div></div><div class="stat"><div class="stat-value">1+</div><div class="stat-label">Проектов за созыв</div></div></div><section class="card"><div class="notice info">Уважительно пропущенные заседания исключаются из личного расчёта. Итоги оцениваются по окончании созыва. Автоматических взысканий нет.</div><div class="table-wrap"><table><thead><tr><th>Член совета</th><th>Заседания ≥70%</th><th>Очно ≥50%</th><th>Голосования ≥75%</th><th>Внутренние комитеты</th><th>Инициативы</th></tr></thead><tbody>${state.members.map(m=>{const r=rows.find(r=>String(r.member_id||r.id)===String(m.id))||{};const attendance=r.attendance_percent??r.attendanceRate??r.attendance,onsite=r.onsite_percent??r.onsiteRate??r.onsite,voting=r.voting_percent??r.voteRate??r.voting;return `<tr><td>${esc(m.name)}</td><td><span class="percent ${Number(attendance)>=70?'good':'bad'}">${percent(attendance)}</span></td><td><span class="percent ${Number(onsite)>=50?'good':'bad'}">${percent(onsite)}</span></td><td><span class="percent ${Number(voting)>=75?'good':'bad'}">${percent(voting)}</span></td><td>${Array.isArray(r.groups)?r.groups.length:r.group_count??'—'}</td><td>${r.initiative_count??state.initiatives.filter(i=>String(i.member_id)===String(m.id)).length}</td></tr>`}).join('')}</tbody></table></div></section>`;}
function rules(){return heading('Устав и правила','Процедуры привязаны к уставу и регламенту Малого совета.')+`<div class="grid"><section class="card"><h3>Правила голосования</h3><div class="row"><span class="row-title">Кворум</span>${badge('9 из 16','good')}</div><div class="row"><span class="row-title">Обычные решения</span><span class="row-meta">Больше половины голосующих</span></div><div class="row"><span class="row-title">Отзыв, вето, выговор совета</span>${badge('11 голосов')}</div><div class="row"><span class="row-title">Изменение устава</span>${badge('11 голосов · ст. 39')}</div><div class="row"><span class="row-title">Выборы председателя</span><span class="row-meta">Наибольшее число голосов</span></div></section><section class="card"><h3>Сроки и ограничения</h3><p>Повестка — за 24 часа. Очередное заседание — не реже одного раза в две недели. Обращения — ответ за 7 календарных дней.</p><p>Дистанционное участие в обычных заседаниях — не более одного в месяц и без двух подряд. Экстренные заседания исключены из ограничения.</p><p>Резолюция по одному предмету — не более трёх попыток за созыв.</p></section></div><section class="card" style="margin-top:18px"><h3>Особенности исходного устава</h3><p>Статья 27 содержит общее правило простого большинства для изменения устава, а специальная статья 39 устанавливает 11 голосов. Программа применяет специальную норму статьи 39 по правилу статьи 38.</p><p>Для предложений инициативных групп в статьях 20 и 23 указаны разные количества подписантов: 10 для передачи предложения в повестку и 5 для направления инициативы председателю. Эти этапы следует различать.</p><div class="actions">${bt('Прочитать устав','reference',{type:'charter'},'secondary')}${bt('Пример протокола 24.10.2026','reference',{type:'protocol'},'outline')}</div>${reference?`<div class="long-text" style="margin-top:25px;border-top:1px solid var(--line);padding-top:25px">${esc(reference)}</div>`:''}</section>`;}

