async function command(cmd,data){if(enhancedCommands[cmd])return enhancedCommands[cmd](data);switch(cmd){case'navigate':page=data.page;localStorage.setItem('council-page',page);render();break;case'open-meeting':meetingId=data.id;page='meetings';localStorage.setItem('council-meeting',meetingId);localStorage.setItem('council-page',page);render();break;case'meeting-tab':meetingTab=data.tab;render();break;case'meeting-list':openDialog('Заседания',[],async()=>{},'Готово');$('#dialog-fields').innerHTML=state.meetings.slice().reverse().map(meetingRow).join('');break;case'logout':await api('/api/logout',{});setState(await api('/api/bootstrap'));render();break;case'action':await action(data,data.action==='vote.cast'?'Ваш голос зафиксирован':'Сохранено');break;case'confirm':openDialog(data.title,[],async()=>{await action({action:data.action,...data.payload});},'Подтвердить',data.description);break;case'meeting-form':meetingForm();break;case'question-form':questionForm();break;case'request-form':requestForm(data.type);break;case'result':showResult(data.question_id);break;case'veto-form':actionForm('Мотивированное вето','question.veto',[f('reason','Обоснование вето','textarea',{required:true,maxLength:10000})],data,'Заявить вето','Вето заявляется до объявления решения вступившим в силу.');break;case'observer-form':actionForm('Приглашённый участник','observer.add',[f('name','Имя','text',{required:true,maxLength:150}),f('status','Форма участия','select',{required:true,options:[['present','Очно'],['remote','Дистанционно']]}),f('role','Статус','select',{required:true,options:[['observer','Наблюдатель'],['coordinator','Координатор']]})],{},'Добавить','Приглашённые участвуют без права голоса.');break;case'excuse-form':{const a=current()?.attendance?.[data.member_id]||{};actionForm('Уважительная причина','attendance.set',[f('excused','Уважительная причина подтверждена','checkbox',{value:!!a.excused}),f('excuse_reason','Причина','textarea',{value:a.excuse_reason||'',maxLength:1000})],{member_id:data.member_id,status:a.status||'absent',identified:!!a.identified},'Сохранить','Подтверждённый пропуск исключается из личного расчёта посещаемости.');break;}case'note-form':actionForm('Запись в протокол','note.add',[questionField(),f('speaker','Выступающий','text',{maxLength:150}),f('text','Сущность предложения / ход обсуждения','textarea',{required:true,maxLength:20000})],{},'Добавить запись','Фиксируйте сущность выступления и точную формулировку предложений.',v=>({...v,question_id:num(v.question_id)}));break;case'member-form':actionForm('Добавить члена совета','member.add',[f('name','Имя и фамилия','text',{required:true,maxLength:150}),f('password','Личный пароль','password',{required:true,minLength:10}),f('telegram','Telegram (необязательно)','text',{maxLength:100}),f('adult','Совершеннолетний','checkbox',{value:true})],{},'Добавить участника','Назначение председателя и секретаря проводится через выборы.');break;case'correspondence-form':actionForm('Новое обращение','correspondence.add',[titleField(),f('text','Текст обращения','textarea',{required:true,maxLength:20000}),memberField('member_id','Адресат — член совета',false),f('group_id','Или адресат — внутренний комитет','select',{options:state.groups.filter(g=>!g.closed_at).map(g=>[g.id,g.name])})],{},'Зарегистрировать','Выберите одного адресата. Срок ответа рассчитается автоматически: 7 календарных дней.',v=>({...v,member_id:num(v.member_id),group_id:num(v.group_id)}));break;case'reply-form':actionForm('Ответ на обращение','correspondence.reply',[f('reply','Ответ','textarea',{required:true,maxLength:20000})],data,'Сохранить ответ');break;case'reference':{const res=await fetch('/api/reference?type='+encodeURIComponent(data.type),{credentials:'same-origin'});if(!res.ok)throw new Error('Не удалось загрузить источник');const text=await res.text();try{const obj=JSON.parse(text);reference=obj.text||obj.content||text;}catch{reference=text;}render();break;}default:throw new Error('Неизвестное действие');}}
document.addEventListener('click',async ev=>{const close=ev.target.closest('[data-close]');if(close){$('#modal').close();return;}const button=ev.target.closest('[data-command]');if(!button||button.disabled)return;try{const data=JSON.parse(button.dataset.payload||'{}');if(button.closest('#modal')&&['open-meeting','navigate'].includes(button.dataset.command))$('#modal').close();button.disabled=true;await command(button.dataset.command,data);}catch(err){if(!err.reported)toast(err.message,true);console.error(err);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('change',async ev=>{if(ev.target.id==='meeting-picker'){meetingId=String(ev.target.value);localStorage.setItem('council-meeting',meetingId);render();}if(ev.target.matches('[data-attendance]')){const member_id=String(ev.target.dataset.attendance),status=ev.target.value,a=current()?.attendance?.[member_id]||{};if(status==='remote'&&!a.identified){ev.target.value=a.status||'absent';openDialog('Дистанционное участие',[f('identified','Личность участника установлена и подтверждена','checkbox',{required:true})],async v=>{if(!v.identified)throw new Error('Подтвердите идентификацию');await action({action:'attendance.set',member_id,status:'remote',identified:true,excused:!!a.excused,excuse_reason:a.excuse_reason||''});},'Зарегистрировать','Дистанционные участники учитываются в кворуме после идентификации. Ограничения месяца и последовательных заседаний проверяются автоматически.');return;}try{await action({action:'attendance.set',member_id,status,identified:status==='remote'?!!a.identified:true,excused:!!a.excused,excuse_reason:a.excuse_reason||''});}catch{render();}}});
$('#dialog-form').addEventListener('submit',async ev=>{ev.preventDefault();const submit=$('#dialog-submit');submit.disabled=true;$('#dialog-error').textContent='';try{await modalSubmit?.();$('#modal').close();}catch(err){$('#dialog-error').textContent=err.message;}finally{submit.disabled=false;}});
async function poll(){if(!state?.me||busy||document.hidden)return;try{const next=await api('/api/state');$('#connection').classList.add('hidden');const signature=JSON.stringify(next.state||next);if(signature!==lastSignature){const active=document.activeElement,preserve=$('#modal').open||active?.matches('input,select,textarea')||document.querySelector('details[open]');if(!preserve){setState(next);render();}}}catch(err){$('#connection').textContent='Соединение прервано. Изменения не отправляются автоматически; повторяем подключение…';$('#connection').classList.remove('hidden');}}

const noteKinds={speech:'Выступление',proposal:'Предложение',decision:'Формулировка решения',remark:'Замечание',break:'Перерыв'};
function draftKey(){return `protocol-draft:${state.me.id}:${meetingId}`;}
function readDraft(){try{return JSON.parse(sessionStorage.getItem(draftKey())||'{}');}catch{return {};}}
function storeDraft(draft){try{sessionStorage.setItem(draftKey(),JSON.stringify(draft));return true;}catch{return false;}}
function quickProtocol(m){
  if(!office()||m.status==='closed')return '';
  const draft=readDraft(),qid=draft.question_id??m.discussion_question_id??m.current_question_id??m.questions[0]?.id??'',q=m.questions.find(q=>q.id===qid),speaker=draft.speaker??m.requests.find(r=>r.status==='granted')?.member_name??'';
  const next=m.questions.find(x=>x.order_num>(q?.order_num||0));
  return `<section class="card protocol-editor"><div class="card-head"><div><div class="eyebrow">Рабочее место секретаря</div><h2>Записать → сохранить → продолжить</h2></div><a class="button outline small" href="/api/protocol/${encodeURIComponent(m.id)}" target="_blank" rel="noopener">Предпросмотр ↗</a></div><form id="quick-protocol"><div class="field-pair"><div><label for="quick-question">Вопрос повестки</label><select name="question_id" id="quick-question"><option value="">Общая запись заседания</option>${m.questions.map(x=>`<option value="${esc(x.id)}" ${x.id===qid?'selected':''}>${esc(x.order_num+'. '+x.title)}</option>`).join('')}</select></div><div><label for="quick-speaker">Выступающий</label><input name="speaker" id="quick-speaker" list="protocol-speakers" maxlength="300" placeholder="Начните вводить имя" value="${esc(speaker)}"><datalist id="protocol-speakers">${[...state.members,...(m.observers||[])].map(x=>`<option value="${esc(x.name)}"></option>`).join('')}</datalist></div></div><div class="note-types" role="group" aria-label="Тип записи">${Object.entries(noteKinds).map(([kind,label])=>`<label><input type="radio" name="kind" value="${kind}" ${(draft.kind||'speech')===kind?'checked':''}>${label}</label>`).join('')}</div><label for="quick-text" class="sr-only">Текст записи в протокол</label><textarea id="quick-text" name="text" rows="4" required maxlength="30000" placeholder="Суть выступления, предложение или точная формулировка решения…">${esc(draft.text||'')}</textarea><div class="quick-actions"><div><button type="submit" class="button">Сохранить запись</button><span class="field-help"> Ctrl+Enter</span></div><span id="draft-state" class="field-help" role="status">${draft.text?'Черновик восстановлен в этом браузере':'Черновик сохраняется в этой вкладке'}</span></div></form><div class="protocol-next"><span>${q?esc(q.title):'Общие записи заседания'}</span><div class="actions">${q?.status==='pending'&&m.status==='active'?act('Открыть голосование','question.open',{question_id:q.id},'secondary small'):''}${q?.status==='opened'?act('Завершить голосование','question.close',{question_id:q.id},'secondary small'):''}${q?.status==='closed'&&!q.announced_at&&!q.veto?act('Объявить результат','question.announce',{question_id:q.id},'secondary small'):''}${next?bt('Следующий вопрос →','protocol-focus',{question_id:next.id},'outline small'):''}</div></div></section>`;
}
function noteTimeline(m){const notes=(m.notes||[]).filter(n=>!n.voided);return notes.length?`<div class="timeline">${notes.map(n=>`<article class="timeline-item"><div class="row-meta">${esc(noteKinds[n.kind]||'Выступление')} · ${esc(n.speaker)} · ${esc(date(n.at))}${n.edited_at?' · исправлено':''}</div><div class="row-meta">${esc(m.questions.find(q=>q.id===n.question_id)?.title||'Общая запись')}</div><div class="long-text">${esc(n.text)}</div>${office()&&m.status!=='closed'&&n.kind!=='decision'?`<div class="actions">${bt('Исправить','note-edit',{note_id:n.id},'text')}${bt('Убрать','note-remove',{note_id:n.id},'text')}</div>`:''}</article>`).join('')}</div>`:'<div class="list-empty">Запишите первое выступление выше. Записи сразу попадут в протокол выбранного вопроса.</div>';}
function publicInbox(){
  const entries=state.submissions||[],statusNames={received:'Новая',in_review:'На рассмотрении',answered:'Ответ готов',closed:'Завершено'};
  return heading('Публичные заявки','Обращения и идеи, поступившие без регистрации.',`<a class="button secondary" href="/public" target="_blank" rel="noopener">Открытая приёмная ↗</a>`)+(office()?`<section class="card">${entries.length?entries.slice().reverse().map(e=>`<article class="intake-item"><div class="card-head"><div><div class="row-meta">№ ${esc(e.id.slice(0,8).toUpperCase())} · ${e.type==='initiative'?'Инициатива':'Обращение'} · ${esc(date(e.created_at))}</div><h3>${esc(e.title)}</h3></div>${badge(statusNames[e.status],e.status==='received'?'warn':'good')}</div><div class="long-text">${esc(e.text)}</div><p class="intake-contact">${esc(e.name)} · ${esc(e.contact)}<br>Адресат: ${esc(e.recipient?.label||'Малый совет')}</p>${e.reply?`<div class="note long-text">${esc(e.reply)}</div>`:''}<div class="actions">${!e.registry_id?act(e.type==='initiative'?'В реестр инициатив':'Принять в работу','submission.accept',{submission_id:e.id},'secondary'):badge('В реестре')}${bt('Ответить','submission-reply',{submission_id:e.id},'outline')}</div></article>`).join(''):empty('Пока нет заявок','Поделитесь ссылкой на открытую приёмную. Заявки появятся здесь автоматически.')}</section>`:empty('Входящие доступны делопроизводителю','Публичную заявку может подать каждый по ссылке выше.'));
}
document.addEventListener('input',e=>{const form=e.target.closest('#quick-protocol');if(!form)return;const old=readDraft(),draft={...old,...Object.fromEntries(new FormData(form)),client_note_id:crypto.randomUUID()};const ok=storeDraft(draft);$('#draft-state').textContent=ok?'Черновик сохранён в этой вкладке':'Черновик не удалось сохранить в браузере';});
document.addEventListener('change',e=>{if(e.target.id!=='quick-question')return;const form=e.target.form;storeDraft({...readDraft(),...Object.fromEntries(new FormData(form))});if(!busy)action({action:'meeting.focus',question_id:e.target.value||null},'').catch(()=>{});});
document.addEventListener('keydown',e=>{if(e.target.closest('#quick-protocol')&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();e.target.closest('form').requestSubmit();}});
document.addEventListener('submit',async e=>{if(e.target.id!=='quick-protocol')return;e.preventDefault();if(busy)return;const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;const draft={...readDraft(),...Object.fromEntries(new FormData(form))};draft.client_note_id||=crypto.randomUUID();storeDraft(draft);form.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=true);try{await action({action:'note.add',...draft,question_id:draft.question_id||null},'Запись добавлена в протокол');storeDraft({question_id:draft.question_id,speaker:draft.speaker,kind:'speech'});render();$('#quick-text')?.focus();}catch{}finally{button.disabled=false;form.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=false);}});
function mandateCases(){const cases=state.meetings.flatMap(m=>(m.questions||[]).filter(q=>q.procedure==='mandate_termination'&&q.result?.passed&&q.announced_at&&(office()||q.candidate_id===state.me.id)).map(q=>({...q,meetingTitle:m.title})));return cases.length?`<section class="card"><h3>Решения о прекращении мандата</h3>${cases.map(q=>`<div class="row"><div class="row-main"><div class="row-title">${esc(memberName(q.candidate_id))}</div><div class="row-meta">${esc(q.title)} · ${esc(q.meetingTitle)}</div>${q.mandate_appeal?`<div class="note">${esc(q.mandate_appeal.reason||q.mandate_appeal.text||'Апелляция зарегистрирована')}</div>`:''}</div><div class="actions">${q.candidate_id===state.me.id?bt('Обжаловать решение','mandate-appeal-form',{question_id:q.id},'secondary small'):''}${office()?bt('Решение вышестоящей инстанции','mandate-resolve-form',{question_id:q.id},'outline small'):''}</div></div>`).join('')}</section>`:'';}
